import { useId } from 'react';

const SKELETON_COUNT = 4;
const MAX_VISIBLE = 10;

export interface Notification {
  id: string;
  message: string;
  timestamp: string;
}

interface NotificationPanelProps {
  notifications?: Notification[];
  loading?: boolean;
}

export function NotificationPanel({ notifications, loading = false }: NotificationPanelProps): JSX.Element {
  const labelId = useId();

  if (loading) {
    return (
      <section aria-labelledby={labelId}>
        <h2 id={labelId}>Notifications</h2>
        <ul>
          {Array.from({ length: SKELETON_COUNT }, (_, i) => (
            <li key={i} aria-label="Loading notification">
              <span className="notification-skeleton" />
            </li>
          ))}
        </ul>
      </section>
    );
  }

  const visible = (notifications ?? []).slice(0, MAX_VISIBLE);

  return (
    <section aria-labelledby={labelId}>
      <h2 id={labelId}>Notifications</h2>
      <ul>
        {visible.map((n) => (
          <li key={n.id} className="notification-item">
            <span className="notification-message">{n.message}</span>
            <time className="notification-timestamp" dateTime={n.timestamp}>
              {n.timestamp}
            </time>
          </li>
        ))}
      </ul>
    </section>
  );
}

