import { useState } from 'react';

type FilterOption = 'All' | 'Reading' | 'Finished' | 'Want to Read';

const FILTER_OPTIONS: FilterOption[] = ['All', 'Reading', 'Finished', 'Want to Read'];

interface FilterBarProps {
  onFilterChange?: (filter: FilterOption) => void;
}

export function FilterBar({ onFilterChange }: FilterBarProps): JSX.Element {
  const [activeFilter, setActiveFilter] = useState<FilterOption>('All');

  function handleClick(filter: FilterOption): void {
    setActiveFilter(filter);
    onFilterChange?.(filter);
  }

  return (
    <div role="group" aria-label="Filter books">
      {FILTER_OPTIONS.map((filter) => (
        <button
          key={filter}
          type="button"
          aria-pressed={activeFilter === filter}
          onClick={() => handleClick(filter)}
        >
          {filter}
        </button>
      ))}
    </div>
  );
}

