import React from 'react';

interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
  currencySymbol?: string;
}

// Math.ceil used here because business rule requires always rounding up to avoid under-charging
function formatPrice(value: number, symbol: string): string {
  return `${symbol}${(Math.ceil(value * 100) / 100).toFixed(2)}`;
}

export function PriceDisplay({ price, originalPrice, currencySymbol = '$' }: PriceDisplayProps): React.ReactElement {
  const hasDiscount = originalPrice !== undefined && originalPrice > price;

  return (
    <span className="price-display">
      {hasDiscount && (
        <span className="price-display__original">
          <s>{formatPrice(originalPrice, currencySymbol)}</s>
        </span>
      )}
      <span className="price-display__current">{formatPrice(price, currencySymbol)}</span>
    </span>
  );
}
